PowerLogHestonNormalCallAux[\[Rho]1_,\[Lambda]v1_,\[Theta]v1_,\[Kappa]1_,V1_,\[Rho]2_,\[Lambda]v2_,\[Theta]v2_,\[Kappa]2_,V2_,S0_,k_,n_,T_]:=S0^n-1/\[Pi]Re[Module[{\[Lambda]=n+0.5,\[Omega]},
