Drift[x_]:=1/2(D[x,S1,S1](Diff[S1].Diff[S1])+D[x,S1,S2](Diff[S1].Diff[S2])+D[x,S2,S2](Diff[S2].Diff[S2])+D[x,V1,V1](Diff[V1].Diff[V1])+D[x,V2,V2](Diff[V2].Diff[V2])+D[x,V3,V3](Diff[V3].Diff[V3]))



\[Nu]projet\[EAcute]Packaged[S1_,S2_,VolS1_,VolS2_,Correl12_, \[Rho]1_,\[Kappa]1_,\[Rho]2_,\[Kappa]2_,\[Rho]3_,\[Kappa]3_]:=Module[{VarVS,VS,\[Alpha]2,\[Beta]2,V1,V2,V3},
\[Beta]2=((1+Correl12) Sqrt[VolS2])/2;\[Alpha]2=(2Correl12)/(1+Correl12) Sqrt[VolS1];V1=VolS1-\[Alpha]2^2;V3=VolS2-\[Beta]2^2;V2=1;
VarVS=S1^2 V1 (2 S1 (V1+V2 \[Alpha]2^2)-2 S2 V2 \[Alpha]2 \[Beta]2) (2 S1 V1+2 V2 \[Alpha]2 (S1 \[Alpha]2-S2 \[Beta]2)+S1 \[Kappa]1 \[Rho]1)+S1^3 V1 \[Kappa]1 (-2 S2 V2 \[Alpha]2 \[Beta]2 \[Rho]1+S1 (\[Kappa]1+2 (V1+V2 \[Alpha]2^2) \[Rho]1))+V2 (S1 \[Alpha]2-S2 \[Beta]2)^2 \[Kappa]2 ((S1 \[Alpha]2-S2 \[Beta]2)^2 \[Kappa]2+(2 S1^2 \[Alpha]2 (V1+V2 \[Alpha]2^2)-2 S1 S2 V2 \[Alpha]2 \[Beta]2 (\[Alpha]2+\[Beta]2)+2 S2^2 \[Beta]2 (V3+V2 \[Beta]2^2)) \[Rho]2)+V2 (2 S1^2 \[Alpha]2 (V1+V2 \[Alpha]2^2)-2 S1 S2 V2 \[Alpha]2 \[Beta]2 (\[Alpha]2+\[Beta]2)+2 S2^2 \[Beta]2 (V3+V2 \[Beta]2^2)) (-2 S1 S2 \[Alpha]2 \[Beta]2 (V2 (\[Alpha]2+\[Beta]2)+\[Kappa]2 \[Rho]2)+S1^2 \[Alpha]2 (2 V1+\[Alpha]2 (2 V2 \[Alpha]2+\[Kappa]2 \[Rho]2))+S2^2 \[Beta]2 (2 V3+\[Beta]2 (2 V2 \[Beta]2+\[Kappa]2 \[Rho]2)))+S2^3 V3 \[Kappa]3 (-2 S1 V2 \[Alpha]2 \[Beta]2 \[Rho]3+S2 (\[Kappa]3+2 (V3+V2 \[Beta]2^2) \[Rho]3))+2 S2^2 V3 (-S1 V2 \[Alpha]2 \[Beta]2+S2 (V3+V2 \[Beta]2^2)) (-2 S1 V2 \[Alpha]2 \[Beta]2+S2 (2 V3+2 V2 \[Beta]2^2+\[Kappa]3 \[Rho]3));
VS=S1^2 V1+S2^2 V3+V2 (S1 \[Alpha]2-S2 \[Beta]2)^2;Sqrt[VarVS/VS]]


BiSuperHestonFondamentalTransform[\[Rho]1_,\[Lambda]v1_,\[Theta]v1_,\[Kappa]1_,V1_,\[Rho]2_,\[Lambda]v2_,\[Theta]v2_,\[Kappa]2_,V2_,\[Rho]3_,\[Lambda]v3_,\[Theta]v3_,\[Kappa]3_,V3_,Z1_,Z2_,\[Alpha]2_,\[Beta]2_,\[Tau]_]:=
Module[{\[Zeta]1,\[Psi]p1 ,\[Psi]m1,A1,arg\[Zeta]1,\[Zeta]2,\[Psi]p2 ,\[Psi]m2,A2,arg\[Zeta]2,\[Zeta]3,\[Psi]p3 ,\[Psi]m3,A3,arg\[Zeta]3,c},
arg\[Zeta]1=(\[Lambda]v1+\[Rho]1 \[Kappa]1 I Z1)^2+\[Kappa]1^2( Z1^2-I Z1);
\[Zeta]1=Sqrt[arg\[Zeta]1];
\[Psi]p1 =-(\[Lambda]v1+\[Rho]1 \[Kappa]1 I Z1)+\[Zeta]1;
\[Psi]m1 =(\[Lambda]v1+\[Rho]1 \[Kappa]1  I Z1)+\[Zeta]1;
A1= -( Z1^2-I Z1)(1-E^(-\[Zeta]1  \[Tau]))/(\[Psi]m1+\[Psi]p1 E^(-\[Zeta]1  \[Tau]));
arg\[Zeta]2=(\[Lambda]v2+\[Rho]2 \[Kappa]2 I (Z1 \[Alpha]2+Z2 \[Beta]2))^2+\[Kappa]2^2( Z1 (-I+Z1) \[Alpha]2^2+2 Z1 Z2 \[Alpha]2 \[Beta]2+Z2 (-I+Z2) \[Beta]2^2);
\[Zeta]2=Sqrt[arg\[Zeta]2];
\[Psi]p2 =-(\[Lambda]v2+\[Rho]2 \[Kappa]2  I (Z1 \[Alpha]2+Z2 \[Beta]2))+\[Zeta]2;
\[Psi]m2 =(\[Lambda]v2+\[Rho]2 \[Kappa]2  I (Z1 \[Alpha]2+Z2 \[Beta]2))+\[Zeta]2;
A2= -( Z1 (-I+Z1) \[Alpha]2^2+2 Z1 Z2 \[Alpha]2 \[Beta]2+Z2 (-I+Z2) \[Beta]2^2)(1-E^(-\[Zeta]2  \[Tau]))/(\[Psi]m2+\[Psi]p2 E^(-\[Zeta]2  \[Tau]));
arg\[Zeta]3=(\[Lambda]v3+\[Rho]3 \[Kappa]3 I Z2)^2+\[Kappa]3^2( Z2^2-I Z2);
\[Zeta]3=Sqrt[arg\[Zeta]3];
\[Psi]p3 =-(\[Lambda]v3+\[Rho]3 \[Kappa]3  I Z2)+\[Zeta]3;
\[Psi]m3 =(\[Lambda]v3+\[Rho]3 \[Kappa]3  I Z2)+\[Zeta]3;
A3= -( Z2^2-I Z2)(1-E^(-\[Zeta]3  \[Tau]))/(\[Psi]m3+\[Psi]p3 E^(-\[Zeta]3  \[Tau]));

c=-( \[Theta]v1 \[Lambda]v1 (\[Tau] \[Psi]p1+2 Log[(\[Psi]m1+E^(-\[Zeta]1 \[Tau]) \[Psi]p1)/(2\[Zeta]1)])/ (\[Kappa]1^2)   )- \[Theta]v2 \[Lambda]v2 (\[Tau] \[Psi]p2+2 Log[(\[Psi]m2+E^(-\[Zeta]2 \[Tau]) \[Psi]p2)/(2\[Zeta]2)])/ (\[Kappa]2^2)   - \[Theta]v3 \[Lambda]v3 (\[Tau] \[Psi]p3+2 Log[(\[Psi]m3+E^(-\[Zeta]3 \[Tau]) \[Psi]p3)/(2\[Zeta]3)])/ (\[Kappa]3^2)   ;
If[Re[c+A1 V1+A2 V2+A3 V3]<-100,0,
E^(c+A1 V1+A2 V2+A3 V3)]
]


phi[x_]:=Exp[-x^2/2]/Sqrt[2Pi]


Nd[x_]:=(Erf[x/Sqrt[2]]+1)/2


LogNormalSpreadDigitaleCall[S1_,S2_,sig1_,sig2_,rho_,k_,t_]:=NIntegrate[phi[x]Nd[-(Log[(k+S2 E^(-1/2 sig2^2 t+sig2 Sqrt[t] x))/(S1 E^(-1/2 sig1^2 t))]-rho sig1 Sqrt[t] x)/(Sqrt[1-rho^2] sig1 Sqrt[t])],{x,-\[Infinity],-1,+\[Infinity]}]


LogNormalSpreadDigitaleCallN[S1_,S2_,sig1_,sig2_,rho_,k_,t_]:=CoeffBasedIntegrate[(Nd[-(Log[(k+S2 E^(-1/2 sig2^2 t+sig2 Sqrt[t] #))/(S1 E^(-1/2 sig1^2 t))]-rho sig1 Sqrt[t] #)/(Sqrt[1-rho^2] sig1 Sqrt[t])])&,ModifiedHermiteCoeffs[20]]


LogNormalSpreadDigitaleCallN[S1_,S2_,sig1_,sig2_,rho_,k_,t_,nbsteps_]:=CoeffBasedIntegrate[(Nd[-(Log[(k+S2 E^(-1/2 sig2^2 t+sig2 Sqrt[t] #))/(S1 E^(-1/2 sig1^2 t))]-rho sig1 Sqrt[t] #)/(Sqrt[1-rho^2] sig1 Sqrt[t])])&,ModifiedHermiteCoeffs[nbsteps]]


(* ::Input:: *)
LogNormalSpreadDigitaleCall[S1_,S2_,sig1_,sig2_,rho_,k_,t_]:=If[k>=0,LogNormalSpreadDigitaleCallN[S1 ,S2 ,sig1,sig2,rho,k,t],1-LogNormalSpreadDigitaleCallN[S2 ,S1 ,sig2,sig1,rho,-k,t]]


(* ::Input:: *)
MesureQTLogNormalSpreadDigitale[S1_,S2_,sig1_,sig2_,rho_,k_,t_]:=LogNormalSpreadDigitaleCall[S1 ,S2 ,sig1,sig2,rho,k,t]


(* ::Input:: *)
MesureQ1LogNormalSpreadDigitale[S1_,S2_,sig1_,sig2_,rho_,k_,t_]:=LogNormalSpreadDigitaleCall[S1 Exp[sig1^2 t],S2 Exp[rho sig1 sig2 t],sig1,sig2,rho,k,t]


(* ::Input:: *)
MesureQ2LogNormalSpreadDigitale[S1_,S2_,sig1_,sig2_,rho_,k_,t_]:=LogNormalSpreadDigitaleCall[S1 Exp[rho sig1 sig2 t],S2 Exp[sig2^2 t],sig1,sig2,rho,k,t]


(* ::Input:: *)
LogNormalSpreadDigitaleCall[S1_,S2_,sig1_,sig2_,rho_,k_,t_,nb_]:=If[k>=0,LogNormalSpreadDigitaleCallN[S1 ,S2 ,sig1,sig2,rho,k,t,nb],1-LogNormalSpreadDigitaleCallN[S2 ,S1 ,sig2,sig1,rho,-k,t,nb]]


(* ::Input:: *)
MesureQTLogNormalSpreadDigitale[S1_,S2_,sig1_,sig2_,rho_,k_,t_,nb_]:=LogNormalSpreadDigitaleCall[S1 ,S2 ,sig1,sig2,rho,k,t,nb]


(* ::Input:: *)
MesureQ1LogNormalSpreadDigitale[S1_,S2_,sig1_,sig2_,rho_,k_,t_,nb_]:=LogNormalSpreadDigitaleCall[S1 Exp[sig1^2 t],S2 Exp[rho sig1 sig2 t],sig1,sig2,rho,k,t,nb]


(* ::Input:: *)
MesureQ2LogNormalSpreadDigitale[S1_,S2_,sig1_,sig2_,rho_,k_,t_,nb_]:=LogNormalSpreadDigitaleCall[S1 Exp[rho sig1 sig2 t],S2 Exp[sig2^2 t],sig1,sig2,rho,k,t,nb]


MesureQ2LogNormalSpreadDigitaleZ[S1_,S2_,sig1_,sig2_,rho_,k_,t_]:=1-MesureQ1LogNormalSpreadDigitale[S2,S1,sig2,sig1,rho,-k,t]


(* ::Input:: *)
LogNormalSpreadOption[S1_,S2_,sig1_,sig2_,rho_,k_,t_]:=S1 MesureQ1LogNormalSpreadDigitale[S1,S2,sig1,sig2,rho,k,t]-S2 MesureQ2LogNormalSpreadDigitale[S1,S2,sig1,sig2,rho,k,t]-k MesureQTLogNormalSpreadDigitale[S1,S2,sig1,sig2,rho,k,t]


(* ::Input:: *)
LogNormalSpreadOption[S1_,S2_,sig1_,sig2_,rho_,k_,t_,nb_]:=S1 MesureQ1LogNormalSpreadDigitale[S1,S2,sig1,sig2,rho,k,t,nb]-S2 MesureQ2LogNormalSpreadDigitale[S1,S2,sig1,sig2,rho,k,t,nb]-k MesureQTLogNormalSpreadDigitale[S1,S2,sig1,sig2,rho,k,t,nb]


LogNormalSpreadDensity[S1_,S2_,sig1_,sig2_,rho_,k_,t_]:=CoeffBasedIntegrate[(E^(1/2 (-#^2+(-rho sig1 Sqrt[t] #+Log[(E^((sig1^2 t)/2) (k+E^(-((sig2^2 t)/2)+sig2 Sqrt[t]#) S2))/S1])^2/((-1+rho^2) sig1^2 t)))/(2 \[Pi] Sqrt[1-rho^2] (k+E^(-((sig2^2 t)/2)+sig2 Sqrt[t] #) S2) sig1 Sqrt[t]))&,ModifiedHermiteCoeffs[20]]


NuRhoMinimunNormalHestonFromBilog[S1_,S2_,sig1_,sig2_,Correl12_,\[Tau]_,\[Rho]_,\[Lambda]v_,LT_,TrueIniVarSpread_,printflag_,LimitGindinkin_]:=
Module[{convexity,convexityTable,VS,DeltaS=0.005,\[Kappa]table,\[Kappa],\[Kappa]inter,prices,\[Kappa]sol,opt1,opt2,opt3,vol1,vol2,vol3,
pente,vols,\[Rho]table,penteTable,\[Rho]inter,\[Rho]sol,\[Rho]s,V0Table,V0inter,V0sol,V0},
If[printflag==1 || MemberQ[printflag,1] ,Print[" @@@@@@  inside NuRhoMinimunNormalHestonFromBilog"]];
opt1=LogNormalSpreadOption[S1,S2,sig1,sig2,Correl12,S1-S2-DeltaS,\[Tau]];
opt2=LogNormalSpreadOption[S1,S2,sig1,sig2,Correl12,S1-S2+DeltaS,\[Tau]];
opt3=LogNormalSpreadOption[S1,S2,sig1,sig2,Correl12,S1-S2,\[Tau]];
vol1=NormalImplicitVol[S1-S2,S1-S2-DeltaS,\[Tau],opt1];
vol2=NormalImplicitVol[S1-S2,S1-S2,\[Tau],opt3];
vol3=NormalImplicitVol[S1-S2,S1-S2+DeltaS,\[Tau],opt2];
If[printflag==1 || MemberQ[printflag,1] ,Print["opt1=",opt1," opt2=",opt2," opt3=",opt3]];
If[printflag==1 || MemberQ[printflag,1] ,Print["vol1=",vol1," vol2=",vol2," vol3=",vol3]];
convexity=vol1+vol3-2*vol2;
pente=vol3-vol1;
If[printflag==1 || MemberQ[printflag,1] ,Print["convexity=",convexity, " pente=",pente," ATMprix=",opt3]];
VS=S1^2 sig1^2+S2^2 sig2^2-2 S1 S2 sig1 sig2  Correl12;
\[Kappa]table={0.0005,0.001,0.0015,0.0025,0.0035};
prices=Timing[Table[{\[Kappa]table[[i]],TransHestonNormalCall[\[Rho],\[Lambda]v,LT TrueIniVarSpread,\[Kappa]table[[i]],TrueIniVarSpread,S1-S2,{S1-S2-DeltaS,S1-S2,S1-S2+DeltaS},\[Tau],LimitGindinkin]},{i,1,Length[\[Kappa]table]}]];
If[printflag==1 || MemberQ[printflag,1] ,Print["PriceTable(for convexity)=",prices[[2]] // MatrixForm]];
vols=Map[({#[[1]],
{NormalImplicitVol[S1-S2,S1-S2-DeltaS,\[Tau],#[[2,1]]],
NormalImplicitVol[S1-S2,S1-S2,\[Tau],#[[2,2]]],
NormalImplicitVol[S1-S2,S1-S2+DeltaS,\[Tau],#[[2,3]]]}})&,
prices[[2]]];
If[printflag==1 || MemberQ[printflag,1] ,Print["VolTable(for convexity)=",vols// MatrixForm]];
convexityTable=Map[({#[[2,1]]+#[[2,3]]-2#[[2,2]],#[[1]]})&,vols];
If[printflag==1 || MemberQ[printflag,1] ,Print["convexityTable=",convexityTable // MatrixForm]];
\[Kappa]sol=Apply[Interpolator5points,Append[Flatten[convexityTable],convexity]];
If[printflag==1 || MemberQ[printflag,1] ,Print["\[Kappa]sol=",\[Kappa]sol]];
\[Rho]table={-0.6,-0.3,-0.1,0,0.5,0.8};
prices=Timing[Table[{\[Rho]table[[i]],TransHestonNormalCall[\[Rho]table[[i]],\[Lambda]v,LT TrueIniVarSpread,\[Kappa]sol,TrueIniVarSpread,S1-S2,{S1-S2-DeltaS,S1-S2+DeltaS},\[Tau],LimitGindinkin]},{i,1,Length[\[Rho]table]}]];
If[printflag==1 || MemberQ[printflag,1] ,Print["prices=",prices]];
vols=Map[({#[[1]],
{NormalImplicitVol[S1-S2,S1-S2-DeltaS,\[Tau],#[[2,1]]],
NormalImplicitVol[S1-S2,S1-S2+DeltaS,\[Tau],#[[2,2]]]}})&,
prices[[2]]];
If[printflag==1 || MemberQ[printflag,1] ,Print["vols=",vols]];
penteTable=Map[({#[[2,2]]-#[[2,1]],#[[1]]})&,vols];
If[printflag==1 || MemberQ[printflag,1] ,Print["penteTable=",penteTable // MatrixForm]];
\[Rho]sol=Apply[Interpolator6points,Append[Flatten[penteTable],pente]];
If[printflag==1 || MemberQ[printflag,1] ,Print["\[Rho]sol=",\[Rho]sol]];
{\[Kappa]sol,\[Rho]sol}]


NuRhoV0MinimunNormalHestonFromBilog[S1_,S2_,sig1_,sig2_,Correl12_,\[Tau]_,\[Rho]_,\[Lambda]v_,LT_,TrueIniVarSpread_,printflag_,LimitGindinkin_]:=
Module[{convexity,convexityTable,VS,DeltaS=0.005,\[Kappa]table,\[Kappa],\[Kappa]inter,prices,\[Kappa]sol,opt1,opt2,opt3,vol1,vol2,vol3,
pente,vols,\[Rho]table,penteTable,\[Rho]inter,\[Rho]sol,\[Rho]s,V0Table,V0inter,V0sol,V0,\[Kappa]sol2,V0sol2},
If[printflag==1 || MemberQ[printflag,1] ,Print[" @@@@@@  inside NuRhoV0MinimunNormalHestonFromBilog"]];
Print["S1=",S1," S2=",S2," sig1=",sig1," sig2=",sig2," Correl12=",Correl12];
opt1=LogNormalSpreadOption[S1,S2,sig1,sig2,Correl12,S1-S2-DeltaS,\[Tau]];
opt2=LogNormalSpreadOption[S1,S2,sig1,sig2,Correl12,S1-S2+DeltaS,\[Tau]];
opt3=LogNormalSpreadOption[S1,S2,sig1,sig2,Correl12,S1-S2,\[Tau]];
vol1=NormalImplicitVol[S1-S2,S1-S2-DeltaS,\[Tau],opt1];
vol2=NormalImplicitVol[S1-S2,S1-S2,\[Tau],opt3];
vol3=NormalImplicitVol[S1-S2,S1-S2+DeltaS,\[Tau],opt2];
If[printflag==1 || MemberQ[printflag,1] ,Print["opt1=",opt1," opt2=",opt2," opt3=",opt3]];
If[printflag==1 || MemberQ[printflag,1] ,Print["vol1=",vol1," vol2=",vol2," vol3=",vol3]];
convexity=vol1+vol3-2*vol2;
pente=vol3-vol1;
If[printflag==1 || MemberQ[printflag,1] ,Print["convexity=",convexity, " pente=",pente," ATMprix=",opt3]];
VS=S1^2 sig1^2+S2^2 sig2^2-2 S1 S2 sig1 sig2  Correl12;
\[Kappa]table={0.0005,0.001,0.004,0.005,0.01};
prices=Timing[Table[{\[Kappa]table[[i]],TransHestonNormalCall[\[Rho],\[Lambda]v,LT TrueIniVarSpread,\[Kappa]table[[i]],TrueIniVarSpread,S1-S2,{S1-S2-DeltaS,S1-S2,S1-S2+DeltaS},\[Tau],LimitGindinkin]},{i,1,Length[\[Kappa]table]}]];
vols=Map[({#[[1]],
{NormalImplicitVol[S1-S2,S1-S2-DeltaS,\[Tau],#[[2,1]]],
NormalImplicitVol[S1-S2,S1-S2,\[Tau],#[[2,2]]],
NormalImplicitVol[S1-S2,S1-S2+DeltaS,\[Tau],#[[2,3]]]}})&,
prices[[2]]];
convexityTable=Map[({#[[2,1]]+#[[2,3]]-2#[[2,2]],Log[#[[1]]]})&,vols];

If[printflag==1 || MemberQ[printflag,1] ,Print["convexityTable=",convexityTable //MatrixForm]];
If[printflag==1 || MemberQ[printflag,1] ,Print["Equivalent nu normalis\[EAcute]=",Map[({#,#/Sqrt[TrueIniVarSpread]})&,\[Kappa]table] //MatrixForm]];
\[Kappa]sol=Exp[Apply[Interpolator5points,Append[Flatten[convexityTable],convexity]]];
If[printflag==1 || MemberQ[printflag,1] ,Print["\[Kappa]sol=",\[Kappa]sol]];
\[Rho]table={-0.6,-0.3,-0.1,0,0.3,0.6};
prices=Timing[Table[{\[Rho]table[[i]],TransHestonNormalCall[\[Rho]table[[i]],\[Lambda]v,LT TrueIniVarSpread,\[Kappa]sol,TrueIniVarSpread,S1-S2,{S1-S2-DeltaS,S1-S2+DeltaS},\[Tau],LimitGindinkin]},{i,1,Length[\[Rho]table]}]];
If[printflag==1 || MemberQ[printflag,1] ,Print["prices(pour la pente)=",prices[[2]]// MatrixForm]];
vols=Map[({#[[1]],
{NormalImplicitVol[S1-S2,S1-S2-DeltaS,\[Tau],#[[2,1]]],
NormalImplicitVol[S1-S2,S1-S2+DeltaS,\[Tau],#[[2,2]]]}})&,
prices[[2]]];
If[printflag==1 || MemberQ[printflag,1] ,Print["vols=",vols// MatrixForm]];
penteTable=Map[({#[[2,2]]-#[[2,1]],Tanh[#[[1]]]})&,vols];
If[printflag==1 || MemberQ[printflag,1] ,Print["penteTable=",penteTable // MatrixForm]];
\[Rho]sol=ArcTanh[Apply[Interpolator6points,Append[Flatten[penteTable],pente]]];
If[printflag==1 || MemberQ[printflag,1] ,Print["\[Rho]sol=",\[Rho]sol]];
V0Table={0.5 TrueIniVarSpread,0.9 TrueIniVarSpread, TrueIniVarSpread, 1.1 TrueIniVarSpread,2 TrueIniVarSpread};
Print["######## arg=","{\[Rho]sol,\[Lambda]v,LT V0Table[,\[Kappa]sol,V0Table,S1-S2,S1-S2,\[Tau],LimitGindinkin}"];
Print["######## arg=",{\[Rho]sol,\[Lambda]v,LT V0Table,\[Kappa]sol,V0Table,S1-S2,S1-S2,\[Tau],LimitGindinkin}];
