CoVarVS0=CoVarVS /.zeroRule;
Apply[Function,{{S1,Si,
alpha11,alpha12,alpha13,alpha14,
alphai1,alphai2,alphai3,alphai4,
rho1,kappaV1,V1,
rho2,kappaV2,V2,
