SmileAlphaDigitalelist[S1_,Si_, \[Rho]1_,\[Nu]1_,V1_,\[Rho]2_,\[Nu]2_,V2_,\[Rho]3_,\[Nu]3_,V3_,\[Rho]4_,\[Nu]4_,V4_,\[Rho]5_,\[Nu]5_,V5_,\[Rho]i_,\[Nu]i_,Vi_,\[Alpha]11_,\[Alpha]12_,\[Alpha]13_,\[Alpha]14_,\[Alpha]i1_,\[Alpha]i2_,\[Alpha]i3_,\[Alpha]i4_,LT_,\[Lambda]_,K_List,T_,LimitGindinkin_,printflag_]:=Module[{\[Rho]projet\[EAcute],\[Nu]projet\[EAcute],prices,VarVSIncrementale,CoVarSVSIncrementale,VS,Sig1,Sig2,Correl12,numinimum,rhominimum,VarVSTotal,CoVarSVSTotal,digitaleprices,forward,shiftL,CompoundK,V0projet\[EAcute],V0minimim,,nbsteps=10,scale=8,microratio=20},

