SmileAlphaDigitaleU1[S1_,Si_, \[Rho]1_,\[Nu]1_,V1_,\[Rho]2_,\[Nu]2_,V2_,\[Rho]3_,\[Nu]3_,V3_,\[Rho]4_,\[Nu]4_,V4_,\[Rho]5_,\[Nu]5_,V5_,\[Rho]i_,\[Nu]i_,Vi_,\[Alpha]11_,\[Alpha]12_,\[Alpha]13_,\[Alpha]14_,\[Alpha]i1_,\[Alpha]i2_,\[Alpha]i3_,\[Alpha]i4_,LT_,\[Lambda]_,K_,T_,LimitGindinkin_,printflag_]:=Module[{forwardSi,forwardS1,\[Rho]projet\[EAcute],\[Nu]projet\[EAcute],prices,VarVS,CoVarSVS,VS,Sig1,Sig2,Correl12,numinimum,rhominimum,VarVSTotal,CoVarSVSTotal,\[Rho]projet\[EAcute]Ini,forward,shiftL,equivalent\[Sigma]1,equivalent\[Sigma]i,equivalent\[Rho],S1Mesure1,SiMesure1},
