forwardS1=AlphaDigitaleForwardU1N[\[Rho]1,\[Nu]1,V1,\[Rho]2,\[Nu]2,V2,\[Rho]3,\[Nu]3,V3,\[Rho]4,\[Nu]4,V4,\[Rho]5,\[Nu]5,V5,\[Rho]i,\[Nu]i,Vi,\[Alpha]11,\[Alpha]12,\[Alpha]13,\[Alpha]14,\[Alpha]i1,\[Alpha]i2,\[Alpha]i3,\[Alpha]i4,\[Lambda],LT,Si,K,T];
forward=forwardS1-forwardSi;
{equivalent\[Sigma]1,equivalent\[Sigma]i,equivalent\[Rho]}=ComputeEquivalentBilogFromAlpha[S1,Si, \[Rho]1,\[Nu]1,V1,\[Rho]2,\[Nu]2,V2,\[Rho]3,\[Nu]3,V3,\[Rho]4,\[Nu]4,V4,\[Rho]5,\[Nu]5,V5,\[Rho]i,\[Nu]i,Vi,\[Alpha]11,\[Alpha]12,\[Alpha]13,\[Alpha]14,\[Alpha]i1,\[Alpha]i2,\[Alpha]i3,\[Alpha]i4,T];
If[printflag==1 || MemberQ[printflag,1] ,Print["equivalent\[Sigma]1=",equivalent\[Sigma]1," equivalent\[Sigma]i=",equivalent\[Sigma]i," equivalent\[Rho]=",equivalent\[Rho]]];
S1Mesure1=S1 Exp[equivalent\[Sigma]1^2T];SiMesure1=Si Exp[equivalent\[Rho] equivalent\[Sigma]1 equivalent\[Sigma]i T];
If[printflag==1 || MemberQ[printflag,1] ,Print["S1Mesure1=",S1Mesure1," SiMesure1=",SiMesure1," forward mesure 1=",S1Mesure1-SiMesure1]];

If[printflag==1 || MemberQ[printflag,1] ,Print["forwardS1=",forwardS1," forwardSi=",forwardSi," forward=",forward]];
(* determination des parametres de smile initial grace au generateur*)
{VS,VarVS,CoVarSVS}=AlphaDigitaleObservable1iz[S1,Si,\[Alpha]11,\[Alpha]12,\[Alpha]13,\[Alpha]14,\[Alpha]i1,\[Alpha]i2,\[Alpha]i3,\[Alpha]i4,\[Rho]1,\[Nu]1,V1,\[Rho]2,\[Nu]2,V2,\[Rho]3,\[Nu]3,V3,\[Rho]4,\[Nu]4,V4,\[Rho]5,\[Nu]5,V5,\[Rho]i,\[Nu]i,Vi];
If[printflag==1 || MemberQ[printflag,1] ,Print["VS=",VS," VarVS=",VarVS," CoVarSVS=",CoVarSVS]];

