{numinimum,rhominimum}=
NuRhoMinimunNormalHestonFromBilog[forwardS1 ,forwardSi,Sig1,Sig2,Correl12,T,\[Rho]projet\[EAcute]Ini,\[Lambda],LT ,VS,0,LimitGindinkin];
If[printflag==1 || MemberQ[printflag,1] ,Print[" Numinimum=",numinimum," rhominimum= ",rhominimum]];
VarVSTotal=VarVS+numinimum^2 VS;
CoVarSVSTotal=CoVarSVS;
\[Rho]projet\[EAcute]=CoVarSVSTotal/Sqrt[VS VarVSTotal];\[Nu]projet\[EAcute]=Sqrt[VarVSTotal/VS];

(* ajustement du kurtosis par effet de vol *)
(* \[Nu]brut= \[Nu]projet\[EAcute] Sqrt[VS/VarRealSpead];\[Nu]normalized=\[Nu]brut/Sqrt[TrueIniVarSpread];*)
If[printflag==1 || MemberQ[printflag,1] ,Print["Normal Heston Parameters=",{{"S0",forward},{"V0",VS},{"\[Rho]",\[Rho]projet\[EAcute]},{"\[Nu]",\[Nu]projet\[EAcute]},
{"\[Nu] normalized",\[Nu]projet\[EAcute]/Sqrt[VS]},{"standard dev equi.",Sqrt[VS]}} //MatrixForm]];
shiftL=0.0001;
forward=S1Mesure1-SiMesure1;(* peut etre enlev\[EAcute]e *)
prices=TransHestonNormalCall[\[Rho]projet\[EAcute],\[Lambda],LT VS,\[Nu]projet\[EAcute],VS,forward,{K-shiftL,K+shiftL},T,LimitGindinkin];
If[printflag==1 || MemberQ[printflag,1] ,Print["prices=",prices]];
S1 (prices[[1]]-prices[[2]])/(2shiftL)
]


